1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Bookmarks — prototype</title>
7	  <style>
8	    :root { color-scheme: light; font-family: Inter, ui-sans-serif, system-ui, sans-serif; color: #18201d; background: #f4f3ed; }
9	    * { box-sizing: border-box; }
10	    body { margin: 0; }
11	    header { display: flex; align-items: center; justify-content: space-between; padding: 22px 7vw; border-bottom: 1px solid #d8d8cf; background: #fbfaf5; }
12	    .brand { font-size: 20px; font-weight: 750; letter-spacing: -.02em; }
13	    main { width: min(920px, 86vw); margin: 72px auto; }
14	    h1 { margin: 0 0 8px; font-size: clamp(30px, 5vw, 48px); letter-spacing: -.04em; }
15	    .lead { margin: 0 0 34px; color: #66706b; font-size: 18px; }
16	    .save-box { display: flex; gap: 10px; padding: 10px; border: 1px solid #ccd1ca; border-radius: 14px; background: white; box-shadow: 0 12px 32px rgba(38, 48, 43, .08); }
17	    input { flex: 1; min-width: 0; border: 0; padding: 12px 14px; font: inherit; outline: none; }
18	    button { border: 0; border-radius: 10px; padding: 12px 18px; background: #175e45; color: white; font: inherit; font-weight: 700; cursor: pointer; }
19	    button:disabled { opacity: .65; cursor: wait; }
20	    #hint { min-height: 24px; margin: 10px 4px 0; color: #66706b; font-size: 14px; }
21	    .collection { margin-top: 62px; }
22	    .collection h2 { font-size: 15px; letter-spacing: .08em; text-transform: uppercase; color: #66706b; }
23	    .empty { margin-top: 18px; padding: 54px 20px; border: 1px dashed #bdc3bc; border-radius: 16px; text-align: center; color: #748079; }
24	    .card { display: none; grid-template-columns: 52px 1fr auto; gap: 16px; align-items: center; margin-top: 18px; padding: 18px; border: 1px solid #d8dcd6; border-radius: 16px; background: white; }
25	    .favicon { width: 52px; height: 52px; display: grid; place-items: center; border-radius: 12px; background: #f1f4f2; color: #175e45; font-weight: 800; }
26	    .title { margin: 0 0 5px; font-size: 18px; }
27	    .description, .url { margin: 0; color: #66706b; font-size: 14px; }
28	    .url { margin-top: 7px; color: #356a58; }
29	    .saved { color: #356a58; font-size: 14px; font-weight: 700; }
30	    @media (max-width: 620px) { .save-box { flex-direction: column; } .card { grid-template-columns: 44px 1fr; } .saved { grid-column: 2; } }
31	  </style>
32	</head>
33	<body>
34	  <header><div class="brand">Keepsake</div><div>All bookmarks</div></header>
35	  <main data-harness-ready="true">
36	    <h1>Save what matters.</h1>
37	    <p class="lead">Paste a link and its details will be filled in for you.</p>
38	    <form id="save-form" class="save-box">
39	      <input id="url" type="url" required autocomplete="off" placeholder="Paste a web address…" aria-label="Web address">
40	      <button id="save" type="submit">Save bookmark</button>
41	    </form>
42	    <p id="hint" role="status"></p>
43	    <section class="collection" aria-labelledby="collection-heading">
44	      <h2 id="collection-heading">Your bookmarks</h2>
45	      <div id="empty" class="empty">No bookmarks yet. Your first saved link will appear here.</div>
46	      <article id="card" class="card">
47	        <div class="favicon">MDN</div>
48	        <div>
49	          <h3 id="title" class="title"></h3>
50	          <p id="description" class="description"></p>
51	          <p id="display-url" class="url"></p>
52	        </div>
53	        <div class="saved">Saved</div>
54	      </article>
55	    </section>
56	  </main>
57	  <script>
58	    const form = document.querySelector('#save-form');
59	    const input = document.querySelector('#url');
60	    const button = document.querySelector('#save');
61	    const hint = document.querySelector('#hint');
62	    form.addEventListener('submit', (event) => {
63	      event.preventDefault();
64	      button.disabled = true;
65	      button.textContent = 'Getting details…';
66	      hint.textContent = 'Reading the page details…';
67	      window.setTimeout(() => {
68	        let host = '';
69	        try { host = new URL(input.value).hostname.replace(/^www\./, ''); } catch (_) {}
70	        const isMdn = host === 'developer.mozilla.org';
71	        document.querySelector('#title').textContent = isMdn ? 'JavaScript | MDN' : `A saved page from ${host || 'the web'}`;
72	        document.querySelector('#description').textContent = isMdn
73	          ? 'JavaScript is a scripting language that enables you to create dynamically updating content.'
74	          : 'Page title and description filled in automatically.';
75	        document.querySelector('#display-url').textContent = input.value;
76	        document.querySelector('#empty').style.display = 'none';
77	        document.querySelector('#card').style.display = 'grid';
78	        button.disabled = false;
79	        button.textContent = 'Save bookmark';
80	        hint.textContent = 'Bookmark saved with its page details.';
81	        input.value = '';
82	      }, 650);
83	    });
84	  </script>
85	</body>
86	</html>
