48	<body>
49	  <header><div class="brand">Keepsake</div><div id="header-label">All bookmarks</div><button id="header-action" class="header-action" type="button">+ Save a link</button></header>
50	  <main data-harness-ready="true">
51	    <h1>Save what matters.</h1>
52	    <p class="lead">Paste a link and its details will be filled in for you.</p>
53	    <form id="save-form" class="save-box">
54	      <input id="url" type="url" required autocomplete="off" placeholder="Paste a web address…" aria-label="Web address">
55	      <button id="save" type="submit">Save bookmark</button>
56	    </form>
57	    <p id="hint" role="status"></p>
58	    <section class="collection" aria-labelledby="collection-heading">
59	      <h2 id="collection-heading">Your bookmarks</h2>
60	      <div id="empty" class="empty">No bookmarks yet. Your first saved link will appear here.</div>
61	      <article id="card" class="card">
62	        <div class="favicon">MDN</div>
63	        <div>
64	          <h3 id="title" class="title"></h3>
65	          <p id="description" class="description"></p>
66	          <p id="display-url" class="url"></p>
67	          <div id="tags" class="tags"><button id="tag-action" class="tag-action" type="button">+ Add a tag</button></div>
68	          <div id="tag-editor" class="tag-editor"><input id="tag-input" type="text" placeholder="Tag name" aria-label="Tag name"><button id="add-tag" type="button">Add</button></div>
69	        </div>
70	        <div class="saved">Saved</div>
71	      </article>
72	    </section>
73	  </main>
74	  <div id="overlay" class="overlay"><section class="dialog"><h2>Save a bookmark</h2><div id="dialog-target"></div></section></div>
75	  <aside id="drawer" class="drawer"><h2>Save a bookmark</h2><div id="drawer-target"></div></aside>
76	  <script>
77	    const form = document.querySelector('#save-form');
78	    const input = document.querySelector('#url');
79	    const button = document.querySelector('#save');
80	    const hint = document.querySelector('#hint');
81	    const method = new URLSearchParams(location.search).get('method') || 'inline';
82	    const flow = new URLSearchParams(location.search).get('flow');
83	    const headerAction = document.querySelector('#header-action');
84	    const overlay = document.querySelector('#overlay');
85	    const drawer = document.querySelector('#drawer');
86	    if (method === 'dialog') {
87	      document.querySelector('#dialog-target').append(form);
88	      document.querySelector('#header-label').style.display = 'none';
89	      headerAction.style.display = 'block';
90	      headerAction.addEventListener('click', () => { overlay.classList.add('open'); input.focus(); });
91	      overlay.addEventListener('click', (event) => { if (event.target === overlay) overlay.classList.remove('open'); });
92	    }
93	    if (method === 'drawer') {
94	      document.querySelector('#drawer-target').append(form);
95	      document.querySelector('#header-label').style.display = 'none';
96	      headerAction.style.display = 'block';
97	      headerAction.addEventListener('click', () => { drawer.classList.add('open'); input.focus(); });
98	    }
99	    if (flow === 'tags') {
100	      document.querySelector('#empty').style.display = 'none';
101	      document.querySelector('#card').style.display = 'grid';
102	      document.querySelector('#title').textContent = 'JavaScript | MDN';
103	      document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
104	      document.querySelector('#display-url').textContent = 'https://developer.mozilla.org/en-US/docs/Web/JavaScript';
105	    }
106	    document.querySelector('#tag-action').addEventListener('click', () => {
107	      document.querySelector('#tag-editor').classList.add('open');
108	      document.querySelector('#tag-input').focus();
109	    });
110	    document.querySelector('#add-tag').addEventListener('click', () => {
111	      const tagInput = document.querySelector('#tag-input');
112	      const name = tagInput.value.trim();
113	      if (!name) return;
114	      const chip = document.createElement('span');
115	      chip.className = 'tag';
116	      chip.textContent = name;
117	      document.querySelector('#tags').prepend(chip);
118	      tagInput.value = '';
119	      document.querySelector('#tag-editor').classList.remove('open');
120	    });
121	    form.addEventListener('submit', (event) => {
122	      event.preventDefault();
123	      button.disabled = true;
124	      button.textContent = 'Getting details…';
125	      hint.textContent = 'Reading the page details…';
126	      window.setTimeout(() => {
127	        let host = '';
128	        try { host = new URL(input.value).hostname.replace(/^www\./, ''); } catch (_) {}
129	        const isMdn = host === 'developer.mozilla.org';
130	        document.querySelector('#title').textContent = isMdn ? 'JavaScript | MDN' : `A saved page from ${host || 'the web'}`;
131	        document.querySelector('#description').textContent = isMdn
132	          ? 'JavaScript is a scripting language that enables you to create dynamically updating content.'
133	          : 'Page title and description filled in automatically.';
134	        document.querySelector('#display-url').textContent = input.value;
135	        document.querySelector('#empty').style.display = 'none';
136	        document.querySelector('#card').style.display = 'grid';
137	        button.disabled = false;
138	        button.textContent = 'Save bookmark';
139	        hint.textContent = 'Bookmark saved with its page details.';
140	        input.value = '';
141	        overlay.classList.remove('open');
142	        drawer.classList.remove('open');
143	      }, 650);
144	    });
145	  </script>
146	</body>
147	</html>
