  document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
  document.querySelector('#display-url').textContent = 'developer.mozilla.org/en-US/docs/Web/JavaScript';
  document.querySelectorAll('.bookmark-card .saved').forEach(status => {
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'later-toggle';
    const iconControl = method === 'icon';
    toggle.textContent = iconControl ? '♡' : 'Read later';
    if (iconControl) toggle.setAttribute('aria-label', 'Add to reading list');
    toggle.addEventListener('click', () => {
      const card = toggle.closest('.bookmark-card');
      card.dataset.readLater = card.dataset.readLater === 'true' ? 'false' : 'true';
      const marked = card.dataset.readLater === 'true';
      toggle.classList.toggle('marked', marked);
      toggle.textContent = iconControl ? (marked ? '♥' : '♡') : (marked ? '✓ In reading list' : 'Read later');
      if (iconControl) toggle.setAttribute('aria-label', marked ? 'Remove from reading list' : 'Add to reading list');
    });
    status.replaceWith(toggle);
  });
}
if (flow === 'manage') {
  document.querySelector('#empty').style.display = 'none';
  document.querySelector('#card').style.display = 'grid';
  document.querySelector('#title').textContent = 'JavaScript | MDN';
  document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
  document.querySelector('#display-url').textContent = 'https://developer.mozilla.org/en-US/docs/Web/JavaScript';
  const status = document.querySelector('#card .saved');
  const management = document.createElement('div');
  management.className = 'manage';
  management.innerHTML = '<button class="manage-button" type="button">Manage</button><div class="manage-menu"><button class="edit-action" type="button">Edit</button><button class="archive-action" type="button">Archive</button><button class="delete-action danger" type="button">Delete</button></div>';
  status.replaceWith(management);
  const menu = management.querySelector('.manage-menu');
  management.querySelector('.manage-button').addEventListener('click', () => menu.classList.toggle('open'));
  management.querySelector('.edit-action').addEventListener('click', () => { menu.classList.remove('open'); document.querySelector('#edit-panel').classList.add('open'); });
  management.querySelector('.archive-action').addEventListener('click', () => { document.querySelector('#card').style.display = 'none'; const notice = document.querySelector('#notice'); notice.style.display = 'block'; notice.textContent = 'Bookmark moved to Archive. It is no longer in All bookmarks.'; });
  management.querySelector('.delete-action').addEventListener('click', () => { menu.classList.remove('open'); if (confirm('Delete this bookmark?')) { document.querySelector('#card').style.display = 'none'; const notice = document.querySelector('#notice'); notice.style.display = 'block'; notice.textContent = 'Bookmark deleted.'; } });
}
