    const matches = card.dataset.search.includes(query);
    card.style.display = matches ? 'grid' : 'none';
    if (matches) visible++;
  });
  document.querySelector('#result-count').textContent = `${visible} ${visible === 1 ? 'bookmark' : 'bookmarks'}`;
});
