1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Bookmarks — prototype</title>
7	  <style>
8	    :root { color-scheme: light; font-family: Inter, ui-sans-serif, system-ui, sans-serif; color: #18201d; background: #f4f3ed; }
9	    * { box-sizing: border-box; }
10	    body { margin: 0; }
11	    header { display: flex; align-items: center; justify-content: space-between; padding: 22px 7vw; border-bottom: 1px solid #d8d8cf; background: #fbfaf5; }
12	    .brand { font-size: 20px; font-weight: 750; letter-spacing: -.02em; }
13	    main { width: min(920px, 86vw); margin: 72px auto; }
14	    h1 { margin: 0 0 8px; font-size: clamp(30px, 5vw, 48px); letter-spacing: -.04em; }
15	    .lead { margin: 0 0 34px; color: #66706b; font-size: 18px; }
16	    .save-box { display: flex; gap: 10px; padding: 10px; border: 1px solid #ccd1ca; border-radius: 14px; background: white; box-shadow: 0 12px 32px rgba(38, 48, 43, .08); }
17	    input { flex: 1; min-width: 0; border: 0; padding: 12px 14px; font: inherit; outline: none; }
18	    button { border: 0; border-radius: 10px; padding: 12px 18px; background: #175e45; color: white; font: inherit; font-weight: 700; cursor: pointer; }
19	    button:disabled { opacity: .65; cursor: wait; }
20	    .header-action { display: none; }
21	    .overlay { display: none; position: fixed; inset: 0; z-index: 5; align-items: center; justify-content: center; padding: 24px; background: rgba(24, 32, 29, .42); }
22	    .overlay.open { display: flex; }
23	    .dialog { width: min(620px, 94vw); padding: 26px; border-radius: 18px; background: #f4f3ed; box-shadow: 0 24px 70px rgba(20, 26, 23, .25); }
24	    .dialog h2, .drawer h2 { margin: 0 0 18px; font-size: 24px; }
25	    .drawer { position: fixed; top: 0; right: -520px; z-index: 6; width: min(480px, 92vw); height: 100vh; padding: 34px 28px; background: #f4f3ed; box-shadow: -20px 0 60px rgba(20, 26, 23, .18); transition: right .22s ease; }
26	    .drawer.open { right: 0; }
27	    .drawer .save-box, .dialog .save-box { flex-direction: column; }
28	    #hint { min-height: 24px; margin: 10px 4px 0; color: #66706b; font-size: 14px; }
29	    #hint.error { color: #a13d35; font-weight: 700; }
30	    .collection { margin-top: 62px; }
31	    .collection h2 { font-size: 15px; letter-spacing: .08em; text-transform: uppercase; color: #66706b; }
32	    .search-box { display: none; margin: 18px 0 8px; padding: 4px 14px; border: 1px solid #ccd1ca; border-radius: 12px; background: white; }
33	    .search-box.visible { display: block; }
34	    .search-box input { width: 100%; }
35	    .result-count { display: none; margin: 10px 2px; color: #66706b; font-size: 14px; }
36	    .view-tabs { display: none; gap: 8px; margin: 18px 0; }
37	    .view-tabs.visible { display: flex; }
38	    .view-tab { border: 1px solid #c9d2cc; background: white; color: #356a58; }
39	    .view-tab.active { border-color: #175e45; background: #175e45; color: white; }
40	    .later-toggle { border: 1px solid #c9d2cc; background: white; color: #356a58; white-space: nowrap; }
41	    .later-toggle.marked { border-color: #175e45; background: #e1eee8; color: #175e45; }
42	    .manage { position: relative; align-self: start; }
43	    .manage-button { border: 1px solid #c9d2cc; background: white; color: #356a58; }
44	    .manage-menu { display: none; position: absolute; right: 0; top: 48px; z-index: 3; width: 150px; padding: 6px; border: 1px solid #d8dcd6; border-radius: 10px; background: white; box-shadow: 0 12px 28px rgba(38,48,43,.14); }
45	    .manage-menu.open { display: grid; gap: 4px; }
46	    .manage-menu button { text-align: left; background: transparent; color: #27342f; font-weight: 600; }
47	    .manage-menu .danger { color: #a13d35; }
48	    .manage.actions { display: grid; gap: 6px; }
49	    .manage.actions button { padding: 8px 12px; border: 1px solid #c9d2cc; background: white; color: #356a58; }
50	    .manage.actions .danger { color: #a13d35; }
51	    .edit-panel { display: none; grid-column: 2 / -1; gap: 10px; padding-top: 14px; border-top: 1px solid #e2e5e0; }
52	    .edit-panel.open { display: grid; }
53	    .edit-panel label { display: grid; gap: 5px; color: #66706b; font-size: 13px; font-weight: 700; }
54	    .edit-panel input { border: 1px solid #c9d2cc; border-radius: 8px; }
55	    .edit-panel button { justify-self: start; }
56	    .notice { display: none; margin-top: 18px; padding: 18px; border-radius: 12px; background: #e8eee9; color: #355447; }
57	    .empty { margin-top: 18px; padding: 54px 20px; border: 1px dashed #bdc3bc; border-radius: 16px; text-align: center; color: #748079; }
58	    .card { display: none; grid-template-columns: 52px 1fr auto; gap: 16px; align-items: center; margin-top: 18px; padding: 18px; border: 1px solid #d8dcd6; border-radius: 16px; background: white; }
59	    .card.highlight { border: 2px solid #2f8a68; box-shadow: 0 0 0 4px #dceee7; }
60	    .favicon { width: 52px; height: 52px; display: grid; place-items: center; border-radius: 12px; background: #f1f4f2; color: #175e45; font-weight: 800; }
61	    .title { margin: 0 0 5px; font-size: 18px; }
62	    .description, .url { margin: 0; color: #66706b; font-size: 14px; }
63	    .url { margin-top: 7px; color: #356a58; overflow-wrap: anywhere; }
64	    .card > div:nth-child(2) { min-width: 0; }
65	    .long-card .title { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
66	    .saved { color: #356a58; font-size: 14px; font-weight: 700; }
67	    .tags { display: flex; align-items: center; gap: 8px; margin-top: 12px; }
68	    .tag { padding: 5px 9px; border-radius: 999px; background: #e1eee8; color: #175e45; font-size: 13px; font-weight: 700; }
69	    .tag-action { padding: 5px 9px; border: 1px solid #c9d2cc; background: transparent; color: #356a58; font-size: 13px; }
70	    .tag-editor { display: none; gap: 8px; margin-top: 12px; }
71	    .tag-editor.open { display: flex; }
72	    .tag-editor input { flex: 0 1 220px; padding: 8px 10px; border: 1px solid #c9d2cc; border-radius: 8px; }
73	    .tag-editor button { padding: 8px 12px; }
74	    @media (max-width: 620px) { .save-box { flex-direction: column; } .card { grid-template-columns: 44px 1fr; } .saved { grid-column: 2; } }
75	  </style>
76	</head>
77	<body>
78	  <header><div class="brand">Keepsake</div><div id="header-label">All bookmarks</div><button id="header-action" class="header-action" type="button">+ Save a link</button></header>
79	  <main data-harness-ready="true">
80	    <h1>Save what matters.</h1>
81	    <p class="lead">Paste a link and its details will be filled in for you.</p>
82	    <form id="save-form" class="save-box">
83	      <input id="url" type="url" required autocomplete="off" placeholder="Paste a web address…" aria-label="Web address">
84	      <button id="save" type="submit">Save bookmark</button>
85	    </form>
86	    <p id="hint" role="status"></p>
87	    <section class="collection" aria-labelledby="collection-heading">
88	      <h2 id="collection-heading">Your bookmarks</h2>
89	      <div id="view-tabs" class="view-tabs"><button id="all-view" class="view-tab active" type="button">All bookmarks</button><button id="later-view" class="view-tab" type="button">Read later</button><button id="archive-view" class="view-tab" type="button" style="display:none">Archive</button></div>
90	      <div id="search-box" class="search-box"><input id="search" type="search" placeholder="Search titles and tags…" aria-label="Search bookmarks"></div>
91	      <p id="result-count" class="result-count"></p>
92	      <div id="empty" class="empty">No bookmarks yet. Your first saved link will appear here.</div>
93	      <article id="card" class="card bookmark-card" data-search="javascript mdn language reference">
94	        <div class="favicon">MDN</div>
95	        <div>
96	          <h3 id="title" class="title"></h3>
97	          <p id="description" class="description"></p>
98	          <p id="display-url" class="url"></p>
99	          <div id="tags" class="tags"><button id="tag-action" class="tag-action" type="button">+ Add a tag</button></div>
100	          <div id="tag-editor" class="tag-editor"><input id="tag-input" type="text" placeholder="Tag name" aria-label="Tag name"><button id="add-tag" type="button">Add</button></div>
101	        </div>
102	        <div class="saved">Saved</div>
103	        <div id="edit-panel" class="edit-panel"><label>Title<input id="edit-title" value="JavaScript | MDN"></label><label>Web address<input id="edit-url" type="url" value="https://developer.mozilla.org/en-US/docs/Web/JavaScript"></label><button id="save-changes" type="button">Save changes</button></div>
104	      </article>
105	      <article id="recipe-card" class="card bookmark-card" data-search="weeknight pasta recipes cooking">
106	        <div class="favicon">WK</div><div><h3 class="title">Five easy weeknight pasta recipes</h3><p class="description">Quick dinners for busy evenings.</p><p class="url">kitchen.example/pasta</p><div class="tags"><span class="tag">cooking</span></div></div><div class="saved">Saved</div>
107	      </article>
108	      <article id="design-card" class="card bookmark-card" data-search="designing calmer interfaces design inspiration">
109	        <div class="favicon">UI</div><div><h3 class="title">Designing calmer interfaces</h3><p class="description">Principles for focused product design.</p><p class="url">design.example/calm</p><div class="tags"><span class="tag">inspiration</span></div></div><div class="saved">Saved</div>
110	      </article>
111	      <div id="notice" class="notice" role="status"></div>
112	    </section>
113	  </main>
114	  <div id="overlay" class="overlay"><section class="dialog"><h2>Save a bookmark</h2><div id="dialog-target"></div></section></div>
115	  <aside id="drawer" class="drawer"><h2>Save a bookmark</h2><div id="drawer-target"></div></aside>
116	  <script>
117	    const form = document.querySelector('#save-form');
118	    const input = document.querySelector('#url');
119	    const button = document.querySelector('#save');
120	    const hint = document.querySelector('#hint');
121	    const method = new URLSearchParams(location.search).get('method') || 'inline';
122	    const flow = new URLSearchParams(location.search).get('flow');
123	    if (flow === 'edge-save') form.noValidate = true;
124	    const headerAction = document.querySelector('#header-action');
125	    const overlay = document.querySelector('#overlay');
126	    const drawer = document.querySelector('#drawer');
127	    if (method === 'dialog') {
128	      document.querySelector('#dialog-target').append(form);
129	      document.querySelector('#header-label').style.display = 'none';
130	      headerAction.style.display = 'block';
131	      headerAction.addEventListener('click', () => { overlay.classList.add('open'); input.focus(); });
132	      overlay.addEventListener('click', (event) => { if (event.target === overlay) overlay.classList.remove('open'); });
133	    }
134	    if (method === 'drawer') {
135	      document.querySelector('#drawer-target').append(form);
136	      document.querySelector('#header-label').style.display = 'none';
137	      headerAction.style.display = 'block';
138	      headerAction.addEventListener('click', () => { drawer.classList.add('open'); input.focus(); });
139	    }
140	    if (flow === 'tags' || flow === 'tag-duplicate') {
141	      document.querySelector('#empty').style.display = 'none';
142	      document.querySelector('#card').style.display = 'grid';
143	      document.querySelector('#title').textContent = 'JavaScript | MDN';
144	      document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
145	      document.querySelector('#display-url').textContent = 'https://developer.mozilla.org/en-US/docs/Web/JavaScript';
146	      if (flow === 'tag-duplicate') {
147	        const existingTag = document.createElement('span'); existingTag.className = 'tag'; existingTag.textContent = 'javascript'; document.querySelector('#tags').prepend(existingTag);
148	      }
149	    }
150	    if (flow === 'search') {
151	      document.querySelector('#empty').style.display = 'none';
152	      document.querySelector('#empty').textContent = 'No bookmarks match this search. Try another title or tag.';
153	      document.querySelector('#search-box').classList.add('visible');
154	      document.querySelector('#result-count').style.display = 'block';
155	      document.querySelectorAll('.bookmark-card').forEach(card => card.style.display = 'grid');
156	      document.querySelector('#title').textContent = 'JavaScript | MDN';
157	      document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
158	      document.querySelector('#display-url').textContent = 'developer.mozilla.org/en-US/docs/Web/JavaScript';
159	      const referenceTag = document.createElement('span');
160	      referenceTag.className = 'tag';
161	      referenceTag.textContent = 'reference';
162	      document.querySelector('#tags').prepend(referenceTag);
163	      document.querySelector('#tag-action').style.display = 'none';
164	      document.querySelector('#result-count').textContent = '3 bookmarks';
165	    }
166	    if (flow === 'read-later') {
167	      document.querySelector('#empty').style.display = 'none';
168	      document.querySelector('#view-tabs').classList.add('visible');
169	      document.querySelectorAll('.bookmark-card').forEach(card => card.style.display = 'grid');
170	      document.querySelector('#title').textContent = 'JavaScript | MDN';
171	      document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
172	      document.querySelector('#display-url').textContent = 'developer.mozilla.org/en-US/docs/Web/JavaScript';
173	      document.querySelectorAll('.bookmark-card .saved').forEach(status => {
174	        const toggle = document.createElement('button');
175	        toggle.type = 'button';
176	        toggle.className = 'later-toggle';
177	        const iconControl = method === 'icon';
178	        toggle.textContent = iconControl ? '♡' : 'Read later';
179	        if (iconControl) toggle.setAttribute('aria-label', 'Add to reading list');
180	        toggle.addEventListener('click', () => {
181	          const card = toggle.closest('.bookmark-card');
182	          card.dataset.readLater = card.dataset.readLater === 'true' ? 'false' : 'true';
183	          const marked = card.dataset.readLater === 'true';
184	          toggle.classList.toggle('marked', marked);
185	          toggle.textContent = iconControl ? (marked ? '♥' : '♡') : (marked ? '✓ In reading list' : 'Read later');
186	          if (iconControl) toggle.setAttribute('aria-label', marked ? 'Remove from reading list' : 'Add to reading list');
187	        });
188	        status.replaceWith(toggle);
189	      });
190	    }
191	    if (flow === 'manage') {
192	      document.querySelector('#empty').style.display = 'none';
193	      document.querySelector('#view-tabs').classList.add('visible');
194	      document.querySelector('#later-view').style.display = 'none';
195	      document.querySelector('#archive-view').style.display = 'block';
196	      document.querySelector('#card').style.display = 'grid';
197	      document.querySelector('#title').textContent = 'JavaScript | MDN';
198	      document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
199	      document.querySelector('#display-url').textContent = 'https://developer.mozilla.org/en-US/docs/Web/JavaScript';
200	      const status = document.querySelector('#card .saved');
201	      const management = document.createElement('div');
202	      management.className = method === 'actions' ? 'manage actions' : 'manage';
203	      management.innerHTML = method === 'actions'
204	        ? '<button class="edit-action" type="button">Edit</button><button class="archive-action" type="button">Archive</button><button class="delete-action danger" type="button">Delete</button>'
205	        : '<button class="manage-button" type="button">Manage</button><div class="manage-menu"><button class="edit-action" type="button">Edit</button><button class="archive-action" type="button">Archive</button><button class="delete-action danger" type="button">Delete</button></div>';
206	      status.replaceWith(management);
207	      const menu = management.querySelector('.manage-menu');
208	      if (menu) management.querySelector('.manage-button').addEventListener('click', () => menu.classList.toggle('open'));
209	      management.querySelector('.edit-action').addEventListener('click', () => { if (menu) menu.classList.remove('open'); document.querySelector('#edit-panel').classList.add('open'); });
210	      management.querySelector('.archive-action').addEventListener('click', () => { const card = document.querySelector('#card'); card.dataset.archived = 'true'; card.style.display = 'none'; const notice = document.querySelector('#notice'); notice.style.display = 'block'; notice.textContent = 'Bookmark moved to Archive. It is no longer in All bookmarks.'; });
211	      management.querySelector('.delete-action').addEventListener('click', () => { if (menu) menu.classList.remove('open'); if (confirm('Delete this bookmark?')) { document.querySelector('#card').style.display = 'none'; const notice = document.querySelector('#notice'); notice.style.display = 'block'; notice.textContent = 'Bookmark deleted.'; } });
212	    }
213	    if (flow === 'duplicate') {
214	      document.querySelector('#empty').style.display = 'none';
215	      document.querySelector('#card').style.display = 'grid';
216	      document.querySelector('#title').textContent = 'JavaScript | MDN';
217	      document.querySelector('#description').textContent = 'JavaScript is a scripting language that enables you to create dynamically updating content.';
218	      document.querySelector('#display-url').textContent = 'https://developer.mozilla.org/en-US/docs/Web/JavaScript';
219	    }
220	    if (flow === 'long') {
221	      document.querySelector('#empty').style.display = 'none';
222	      const card = document.querySelector('#card'); card.style.display = 'grid'; card.classList.add('long-card');
223	      const longTitle = 'A comprehensive field guide to organizing, finding, revisiting, and preserving useful research from across the web';
224	      document.querySelector('#title').textContent = longTitle; document.querySelector('#title').title = longTitle;
225	      document.querySelector('#description').textContent = 'An in-depth reference with practical examples for readers who collect a large amount of material over time.';
226	      document.querySelector('#display-url').textContent = 'https://knowledge.example.com/library/research/organizing-and-preserving-useful-resources?edition=complete&source=reading-list';
227	    }
228	    document.querySelector('#save-changes').addEventListener('click', () => {
229	      const editedUrl = document.querySelector('#edit-url').value;
230	      let validEditedUrl = false;
231	      try { const parsed = new URL(editedUrl); validEditedUrl = parsed.protocol === 'http:' || parsed.protocol === 'https:'; } catch (_) {}
232	      if (!validEditedUrl) {
233	        const notice = document.querySelector('#notice'); notice.style.display = 'block'; notice.style.color = '#a13d35'; notice.textContent = 'Enter a complete web address before saving changes.';
234	        document.querySelector('#edit-url').focus();
235	        return;
236	      }
237	      document.querySelector('#title').textContent = document.querySelector('#edit-title').value;
238	      document.querySelector('#display-url').textContent = editedUrl;
239	      document.querySelector('#edit-panel').classList.remove('open');
240	      const notice = document.querySelector('#notice'); notice.style.display = 'block'; notice.textContent = 'Changes saved.';
241	    });
242	    document.querySelector('#all-view').addEventListener('click', () => {
243	      document.querySelectorAll('.bookmark-card').forEach(card => card.style.display = (flow === 'manage' && card.id !== 'card') || card.dataset.archived === 'true' ? 'none' : 'grid');
244	      document.querySelector('#all-view').classList.add('active');
245	      document.querySelector('#later-view').classList.remove('active');
246	      document.querySelector('#archive-view').classList.remove('active');
247	    });
248	    document.querySelector('#later-view').addEventListener('click', () => {
249	      let laterCount = 0;
250	      document.querySelectorAll('.bookmark-card').forEach(card => { const marked = card.dataset.readLater === 'true'; card.style.display = marked ? 'grid' : 'none'; if (marked) laterCount++; });
251	      document.querySelector('#empty').textContent = 'Your reading list is empty. Mark a bookmark “Read later” to see it here.';
252	      document.querySelector('#empty').style.display = laterCount === 0 ? 'block' : 'none';
253	      document.querySelector('#later-view').classList.add('active');
254	      document.querySelector('#all-view').classList.remove('active');
255	    });
256	    document.querySelector('#archive-view').addEventListener('click', () => {
257	      let archiveCount = 0;
258	      document.querySelectorAll('.bookmark-card').forEach(card => { const archived = card.dataset.archived === 'true'; card.style.display = archived ? 'grid' : 'none'; if (archived) archiveCount++; });
259	      document.querySelector('#empty').textContent = 'Your archive is empty. Bookmarks you set aside will appear here.';
260	      document.querySelector('#empty').style.display = archiveCount === 0 ? 'block' : 'none';
261	      document.querySelector('#archive-view').classList.add('active');
262	      document.querySelector('#all-view').classList.remove('active');
263	      const management = document.querySelector('#card .manage');
264	      if (management && document.querySelector('#card').dataset.archived === 'true') {
265	        management.innerHTML = '<button class="manage-button restore-action" type="button">Restore</button>';
266	        management.querySelector('.restore-action').addEventListener('click', () => {
267	          document.querySelector('#card').dataset.archived = 'false';
268	          document.querySelector('#card').style.display = 'none';
269	          const notice = document.querySelector('#notice'); notice.style.display = 'block'; notice.textContent = 'Bookmark restored to All bookmarks.';
270	        });
271	      }
272	    });
273	    document.querySelector('#search').addEventListener('input', (event) => {
274	      const query = event.target.value.trim().toLowerCase();
275	      let visible = 0;
276	      document.querySelectorAll('.bookmark-card').forEach(card => {
277	        const matches = card.dataset.search.includes(query);
278	        card.style.display = matches ? 'grid' : 'none';
279	        if (matches) visible++;
280	      });
281	      document.querySelector('#result-count').textContent = `${visible} ${visible === 1 ? 'bookmark' : 'bookmarks'}`;
282	      if (flow === 'search') document.querySelector('#empty').style.display = visible === 0 ? 'block' : 'none';
283	    });
284	    document.querySelector('#tag-action').addEventListener('click', () => {
285	      document.querySelector('#tag-editor').classList.add('open');
286	      document.querySelector('#tag-input').focus();
287	    });
288	    document.querySelector('#add-tag').addEventListener('click', () => {
289	      const tagInput = document.querySelector('#tag-input');
290	      const name = tagInput.value.trim();
291	      if (!name) return;
292	      const existingNames = [...document.querySelectorAll('#tags .tag')].map(tag => tag.textContent.toLowerCase());
293	      if (existingNames.includes(name.toLowerCase())) {
294	        hint.classList.add('error'); hint.textContent = 'This bookmark already has that tag.'; return;
295	      }
296	      const chip = document.createElement('span');
297	      chip.className = 'tag';
298	      chip.textContent = name;
299	      document.querySelector('#tags').prepend(chip);
300	      tagInput.value = '';
301	      document.querySelector('#tag-editor').classList.remove('open');
302	    });
303	    form.addEventListener('submit', (event) => {
304	      event.preventDefault();
305	      hint.classList.remove('error');
306	      if (flow === 'duplicate' && input.value.replace(/\/$/, '') === 'https://developer.mozilla.org/en-US/docs/Web/JavaScript') {
307	        hint.textContent = 'This address is already saved. We highlighted the existing bookmark.';
308	        document.querySelector('#card').classList.add('highlight');
309	        return;
310	      }
311	      if (flow === 'edge-save') {
312	        let valid = false;
313	        try { const parsed = new URL(input.value); valid = parsed.protocol === 'http:' || parsed.protocol === 'https:'; } catch (_) {}
314	        if (!valid) {
315	          hint.classList.add('error');
316	          hint.textContent = 'Enter a complete web address, such as https://example.com';
317	          input.focus();
318	          return;
319	        }
320	      }
321	      button.disabled = true;
322	      button.textContent = 'Getting details…';
323	      hint.textContent = 'Reading the page details…';
324	      window.setTimeout(() => {
325	        let host = '';
326	        try { host = new URL(input.value).hostname.replace(/^www\./, ''); } catch (_) {}
327	        const isMdn = host === 'developer.mozilla.org';
328	        const detailsUnavailable = flow === 'edge-save' && host === 'example.invalid';
329	        document.querySelector('#title').textContent = detailsUnavailable ? host : (isMdn ? 'JavaScript | MDN' : `A saved page from ${host || 'the web'}`);
330	        document.querySelector('#description').textContent = detailsUnavailable
331	          ? 'Page details unavailable. You can edit this bookmark later.'
332	          : isMdn
333	          ? 'JavaScript is a scripting language that enables you to create dynamically updating content.'
334	          : 'Page title and description filled in automatically.';
335	        document.querySelector('#display-url').textContent = input.value;
336	        document.querySelector('#empty').style.display = 'none';
337	        document.querySelector('#card').style.display = 'grid';
338	        button.disabled = false;
339	        button.textContent = 'Save bookmark';
340	        hint.textContent = detailsUnavailable ? 'Bookmark saved, but its page details could not be retrieved.' : 'Bookmark saved with its page details.';
341	        input.value = '';
342	        overlay.classList.remove('open');
343	        drawer.classList.remove('open');
344	      }, 650);
345	    });
346	  </script>
347	</body>
348	</html>
